values ('ancla-paes-ciencias', '1.0', 'paes-ciencias', 'admision-2027.v1', 'review', '{"estado_autoria":"contenido_docente_revisado","aviso":"Los 12 ítems están aprobados por el docente: A-01 a A-03 el 2026-08-02 y B-01 a D-03 el 2026-08-03. El banco queda cerrado en v1.0. Los gates físicos y operativos de liberación siguen pendientes: esto no habilita por sí solo la aplicación.","fuente_local":"docencia_2026/10_REFERENCE/ref-banco-ancla-paes-ciencias-v1.md"}'::jsonb)
