insert into private.items (framework_id, framework_version, item_id, item_version, unit_code, criterion_code, axis_code, stimulus_format, stimulus, prompt, alternatives, answer_key, answer_key_status, metadata)
values ('paes-ciencias', 'admision-2027.v1', 'A-01', '1.0', 'BIO-04.05', 'HC-02.C6', 'Biología', 'tabla_de_grupos', '{"tipo":"tabla","introduccion":"Un grupo de estudiantes quiere saber si el color de la luz afecta la germinación de semillas de rabanito. Prepara tres bandejas y las mantiene siete días:","columnas":["Bandeja","Color de luz","Temperatura","Agua diaria","Semillas sembradas","Semillas germinadas al día 7"],"filas":[["A","Blanca","22 °C","10 mL",50,41],["B","Roja","22 °C","10 mL",50,38],["C","Azul","22 °C","10 mL",50,44]],"texto_alternativo":"Tabla de tres bandejas; varía el color de la luz; temperatura, agua y semillas sembradas son iguales en las tres; la última columna registra cuántas semillas germinaron."}'::jsonb, '¿Cuál es la variable dependiente de esta investigación?', '[{"id":"A","texto":"El color de la luz de cada bandeja","diagnostico":"Confunde la variable independiente con la dependiente: identifica lo que se manipula cuando se le pide lo que se mide."},{"id":"B","texto":"El número de semillas germinadas al día 7","diagnostico":"Clave."},{"id":"C","texto":"La temperatura de 22 °C","diagnostico":"Trata una variable controlada como si fuera la respuesta del sistema."},{"id":"D","texto":"Las 50 semillas sembradas por bandeja","diagnostico":"Confunde la condición inicial estandarizada con el resultado medido. Ambas son \"semillas\": discrimina lectura de estructura, no de vocabulario."}]'::jsonb, 'B', 'ok', '{"unidad_rol":"contexto","estado_revision":"revisado_docente","razonamiento_esperado":"La dependiente es la que se mide y se espera que responda. Tres columnas son idénticas entre bandejas (no pueden ser la respuesta), una varía por diseño (es la manipulada) y solo una registra un resultado obtenido al final.","por_que_no_mide_contenido":"No requiere saber nada de germinación ni fotosíntesis: la estructura de la tabla contiene toda la información. El rabanito es escenario, no materia."}'::jsonb)
