values ('paes-ciencias', 'admision-2027.v1', 'B-01', '1.0', 'BIO-04.04', 'HC-03.C1', 'Biología', 'tabla_bases_distintas', '{"tipo":"tabla","introduccion":"En un estudio de regeneración de bosque se contaron las plántulas presentes en tres sectores:","columnas":["Sector","Plántulas contadas","Superficie del sector"],"filas":[["Norte",240,"400 m²"],["Centro",180,"200 m²"],["Sur",300,"600 m²"]],"texto_alternativo":"Tabla de tres sectores con el número de plántulas contadas y la superficie de cada sector; las superficies son distintas entre sí."}'::jsonb, '¿En qué sector la regeneración fue más densa?', '[{"id":"A","texto":"Centro, con 0,9 plántulas por m²","diagnostico":"Clave."},{"id":"B","texto":"Sur, porque tiene el mayor número de plántulas","diagnostico":"Compara números brutos ignorando que las superficies difieren. Es el error nominal del criterio."},{"id":"C","texto":"Norte, porque tiene una superficie intermedia","diagnostico":"Elige por una magnitud que no responde la pregunta; confunde el tamaño de la muestra con el resultado."},{"id":"D","texto":"No se puede saber, porque los sectores tienen superficies distintas","diagnostico":"Confunde \"requiere una operación\" con \"falta información\". La tabla trae todo lo necesario."}]'::jsonb, 'A', 'ok', '{"unidad_rol":"contexto","estado_revision":"revisado_docente","razonamiento_esperado":"Densidad es plántulas por unidad de superficie. Norte 240/400 = 0,6; Centro 180/200 = 0,9; Sur 300/600 = 0,5. El sector con más plántulas totales es el menos denso.","por_que_no_mide_contenido":"No requiere saber nada de regeneración ni de bosques. La operación es una división y la trampa es no hacerla."}'::jsonb)
