insert into private.items (framework_id, framework_version, item_id, item_version, unit_code, criterion_code, axis_code, stimulus_format, stimulus, prompt, alternatives, answer_key, answer_key_status, metadata)
values ('paes-ciencias', 'admision-2027.v1', 'B-02', '1.0', 'FIS-03.01', 'HC-03.C1', 'Física', 'grafico_lineas_eje_truncado', '{"tipo":"grafico_lineas","titulo":"Temperatura durante 30 minutos","eje_x":{"etiqueta":"Tiempo (minutos)","min":0,"max":30,"marcas":[0,5,10,15,20,25,30]},"eje_y":{"etiqueta":"Temperatura (°C)","min":68,"max":72,"marcas":[68,69,70,71,72],"truncado":true},"puntos":[{"x":0,"y":71.8},{"x":5,"y":71.2},{"x":10,"y":70.6},{"x":15,"y":70.1},{"x":20,"y":69.5},{"x":25,"y":68.9},{"x":30,"y":68.4}],"texto_alternativo":"Gráfico de líneas. Eje horizontal: tiempo en minutos, de 0 a 30, con marcas cada 5. Eje vertical: temperatura en grados Celsius, de 68 a 72, con marcas cada 1. La línea desciende de forma pareja desde poco menos de 72 en el minuto 0 hasta poco más de 68 en el minuto 30, pasando por 70 alrededor del minuto 15."}'::jsonb, '¿Qué afirmación describe correctamente lo ocurrido en los 30 minutos?', '[{"id":"A","texto":"La temperatura cayó a menos de la mitad de su valor inicial","diagnostico":"Lee la altura del trazo como si el eje partiera en cero. Es el error nominal del criterio."},{"id":"B","texto":"La temperatura se mantuvo prácticamente constante","diagnostico":"Sobrecorrección: descarta un cambio real y sistemático de 3,4 °C por saber que el eje engaña."},{"id":"C","texto":"La temperatura bajó rápido al principio y se estabilizó al final","diagnostico":"Describe una forma que el gráfico no tiene: el descenso es parejo. Responde con la curva de enfriamiento que espera ver."},{"id":"D","texto":"La temperatura bajó unos 3 °C de forma aproximadamente constante","diagnostico":"Clave."}]'::jsonb, 'D', 'ok', '{"unidad_rol":"contexto","estado_revision":"revisado_docente","razonamiento_esperado":"Antes de interpretar la pendiente hay que leer el rango del eje. 71,8 → 68,4 son 3,4 °C en 30 minutos, con caídas de ~0,6 °C cada 5 minutos: un descenso pequeño pero sostenido, que el rango estrecho del eje magnifica visualmente.","por_que_no_mide_contenido":"No exige la ley de enfriamiento ni termodinámica. Exige mirar el eje antes que el trazo."}'::jsonb)
