insert into private.items (framework_id, framework_version, item_id, item_version, unit_code, criterion_code, axis_code, stimulus_format, stimulus, prompt, alternatives, answer_key, answer_key_status, metadata)
values ('paes-ciencias', 'admision-2027.v1', 'C-01', '1.0', 'BIO-04.01', 'HC-03.C3', 'Biología', 'estudio_observacional', '{"tipo":"texto","texto":"En 40 parcelas de un mismo campo se midió la altura de las plantas y se registró la cantidad de hongos presentes en sus raíces. Las plantas más altas tendieron a presentar más hongos en la raíz. No se manipuló ninguna condición: solo se observó y se midió.","texto_alternativo":"Estudio observacional en 40 parcelas: mayor altura de las plantas se asocia con más hongos en sus raíces; no se manipuló ninguna condición."}'::jsonb, '¿Cuál conclusión se sostiene con esta evidencia?', '[{"id":"A","texto":"Los hongos de la raíz hacen crecer más a las plantas","diagnostico":"Infiere causa desde una asociación observada. Es el error nominal del criterio."},{"id":"B","texto":"Las plantas más altas producen más hongos en su raíz","diagnostico":"Mismo salto causal, en sentido inverso. Distingue a quien rechaza la causalidad de quien solo invierte la flecha."},{"id":"C","texto":"En estas 40 parcelas, mayor altura se asoció a más hongos en la raíz","diagnostico":"Clave."},{"id":"D","texto":"Los hongos son necesarios para que las plantas crezcan","diagnostico":"Causalidad más una condición de necesidad que ningún dato observacional puede establecer."}]'::jsonb, 'C', 'ok', '{"unidad_rol":"contexto","estado_revision":"revisado_docente","razonamiento_esperado":"El estudio observó, no manipuló. Sin una variable controlada por el investigador, la conclusión sostenible describe la asociación y su alcance —estas parcelas— sin afirmar quién causa a quién ni si alguna es indispensable.","por_que_no_mide_contenido":"No exige saber qué son las micorrizas ni cómo interactúan hongos y raíces. De hecho, quien sí lo sabe está en riesgo de elegir A por conocimiento externo: el ítem pide concluir desde la evidencia presentada, no desde lo que uno ya cree."}'::jsonb)
on conflict (framework_id, framework_version, item_id, item_version) do update set unit_code = excluded.unit_code, criterion_code = excluded.criterion_code, axis_code = excluded.axis_code, stimulus_format = excluded.stimulus_format, stimulus = excluded.stimulus, prompt = excluded.prompt, alternatives = excluded.alternatives, answer_key = excluded.answer_key, answer_key_status = excluded.answer_key_status, metadata = excluded.metadata;

