insert into private.items (framework_id, framework_version, item_id, item_version, unit_code, criterion_code, axis_code, stimulus_format, stimulus, prompt, alternatives, answer_key, answer_key_status, metadata)
values ('paes-ciencias', 'admision-2027.v1', 'C-02', '1.0', 'FIS-02.06', 'HC-03.C3', 'Física', 'tabla_extrapolacion', '{"tipo":"tabla","introduccion":"Se colgaron masas de un resorte y se midió cuánto se estiraba:","columnas":["Masa colgada","100 g","200 g","300 g","400 g","500 g"],"filas":[["Estiramiento","2,0 cm","4,1 cm","5,9 cm","8,0 cm","10,1 cm"]],"texto_alternativo":"Tabla con cinco masas entre 100 y 500 gramos y su estiramiento correspondiente, entre 2,0 y 10,1 centímetros; la relación es aproximadamente proporcional."}'::jsonb, '¿Cuál conclusión se sostiene con estos datos?', '[{"id":"A","texto":"Entre 100 y 500 g, el estiramiento fue aproximadamente proporcional a la masa","diagnostico":"Clave."},{"id":"B","texto":"Con 5 000 g, el resorte se estiraría unos 101 cm","diagnostico":"Extrapola diez veces más allá del rango probado, donde el resorte podría deformarse de forma permanente. Es el error nominal del criterio."},{"id":"C","texto":"Cualquier resorte se estira de forma proporcional a la masa colgada","diagnostico":"Generaliza de un resorte a todos los resortes: excede la población, no el rango."},{"id":"D","texto":"El resorte se estira 2 cm por cada 100 g exactos","diagnostico":"Presenta como exacta una relación aproximada, ignorando la dispersión de los datos."}]'::jsonb, 'A', 'ok', '{"unidad_rol":"contexto","estado_revision":"revisado_docente","razonamiento_esperado":"Los datos sostienen una relación aproximadamente proporcional dentro del intervalo medido y para este resorte. Toda afirmación que salga de ese intervalo, de este resorte, o que convierta lo aproximado en exacto, excede la evidencia.","por_que_no_mide_contenido":"No exige conocer la ley de Hooke ni el límite elástico. Basta notar qué rango se probó y qué afirma cada alternativa."}'::jsonb)
