insert into private.items (framework_id, framework_version, item_id, item_version, unit_code, criterion_code, axis_code, stimulus_format, stimulus, prompt, alternatives, answer_key, answer_key_status, metadata)
values ('paes-ciencias', 'admision-2027.v1', 'C-03', '1.0', 'QUI-03.08', 'HC-03.C3', 'Química', 'comparacion_experimental', '{"tipo":"texto","texto":"Se compararon dos quitamanchas, X e Y, aplicándolos sobre manchas de aceite en tela de algodón. En 20 pruebas por producto, X eliminó la mancha por completo en 17 casos e Y en 9.","texto_alternativo":"Comparación de dos quitamanchas sobre manchas de aceite en algodón: X eliminó 17 de 20 e Y eliminó 9 de 20."}'::jsonb, '¿Cuál conclusión se sostiene con esta evidencia?', '[{"id":"A","texto":"X es más eficaz que Y para cualquier tipo de mancha","diagnostico":"Generaliza a tipos de mancha que nunca se probaron."},{"id":"B","texto":"Sobre manchas de aceite en algodón, X eliminó la mancha más veces que Y","diagnostico":"Clave."},{"id":"C","texto":"X es el mejor quitamanchas disponible en el mercado","diagnostico":"Generaliza a productos que no participaron en la comparación."},{"id":"D","texto":"El aceite es más fácil de remover que otras manchas","diagnostico":"Afirma sobre una comparación que el estudio no hizo: nunca hubo otro tipo de mancha."}]'::jsonb, 'B', 'ok', '{"unidad_rol":"contexto","estado_revision":"revisado_docente","razonamiento_esperado":"El estudio comparó dos productos, un tipo de mancha y un tipo de tela. La conclusión sostenible nombra esas tres condiciones. A, C y D expanden cada una un eje distinto: tipo de mancha, universo de productos y comparación entre manchas.","por_que_no_mide_contenido":"No exige saber por qué un tensoactivo remueve grasa. Exige comparar el alcance de cada afirmación con el alcance de lo que se probó."}'::jsonb)
on conflict (framework_id, framework_version, item_id, item_version) do update set unit_code = excluded.unit_code, criterion_code = excluded.criterion_code, axis_code = excluded.axis_code, stimulus_format = excluded.stimulus_format, stimulus = excluded.stimulus, prompt = excluded.prompt, alternatives = excluded.alternatives, answer_key = excluded.answer_key, answer_key_status = excluded.answer_key_status, metadata = excluded.metadata;

