insert into private.items (framework_id, framework_version, item_id, item_version, unit_code, criterion_code, axis_code, stimulus_format, stimulus, prompt, alternatives, answer_key, answer_key_status, metadata)
values ('paes-ciencias', 'admision-2027.v1', 'D-01', '1.0', 'BIO-04.05', 'HC-04.C1', 'Biología', 'variables_confundidas', '{"tipo":"texto","texto":"Para probar si un fertilizante mejora el crecimiento, un grupo prepara dos conjuntos de macetas con la misma especie:\n\nGrupo 1: con fertilizante, ubicado dentro de un invernadero.\nGrupo 2: sin fertilizante, ubicado en el patio exterior.\n\nA las seis semanas, las plantas del Grupo 1 son notoriamente más altas. El grupo concluye que el fertilizante funciona.","texto_alternativo":"Dos grupos de macetas difieren simultáneamente en el uso de fertilizante y en su ubicación; el grupo con fertilizante en invernadero crece más."}'::jsonb, '¿Cuál es el principal problema de este diseño?', '[{"id":"A","texto":"Seis semanas es un plazo demasiado corto para evaluar crecimiento","diagnostico":"Objeción plausible pero secundaria: aunque el plazo fuera mayor, la conclusión seguiría sin sostenerse. Confunde una limitación con el defecto que invalida."},{"id":"B","texto":"No se midió el peso de las plantas, solo la altura","diagnostico":"Cuestiona el indicador. El diseño podría medir cinco variables y el problema persistiría."},{"id":"C","texto":"El número de macetas por grupo no está indicado","diagnostico":"Objeción real sobre el reporte, no sobre la lógica del diseño."},{"id":"D","texto":"Los grupos difieren en fertilizante y en ubicación a la vez, así que la diferencia no puede atribuirse a uno solo","diagnostico":"Clave."}]'::jsonb, 'D', 'ok', '{"unidad_rol":"contexto","estado_revision":"revisado_docente","razonamiento_esperado":"Para atribuir el efecto a una variable, los grupos deben diferir solo en ella. Acá difieren en dos, y el invernadero por sí solo explicaría el resultado. Los distractores son objeciones legítimas pero no invalidantes: el ítem discrimina entre \"algo mejorable\" y \"esto no permite concluir\".","por_que_no_mide_contenido":"No exige saber qué hace un fertilizante. La falla es estructural y visible en la descripción de los grupos."}'::jsonb)
on conflict (framework_id, framework_version, item_id, item_version) do update set unit_code = excluded.unit_code, criterion_code = excluded.criterion_code, axis_code = excluded.axis_code, stimulus_format = excluded.stimulus_format, stimulus = excluded.stimulus, prompt = excluded.prompt, alternatives = excluded.alternatives, answer_key = excluded.answer_key, answer_key_status = excluded.answer_key_status, metadata = excluded.metadata;

