values ('paes-ciencias', 'admision-2027.v1', 'D-02', '1.0', 'FIS-04.05', 'HC-04.C1', 'Física', 'estudio_sin_comparacion', '{"tipo":"texto","texto":"Una familia instala aislante térmico en su casa a fines de marzo. Compara su boleta de electricidad de julio con la de marzo del mismo año y encuentra que el consumo bajó un 22 %. Concluye que el aislante produjo ese ahorro.","texto_alternativo":"Una familia compara el consumo eléctrico de marzo y julio después de instalar aislante térmico y atribuye al aislante una baja de 22 por ciento."}'::jsonb, '¿Qué debilita más esta conclusión?', '[{"id":"A","texto":"Una sola familia es una muestra demasiado pequeña","diagnostico":"Objeción de generalización, no de validez interna. Aun con 500 familias el mismo problema persistiría."},{"id":"B","texto":"No se indica el precio del kilowatt-hora en cada mes","diagnostico":"Relevante para el gasto en pesos, pero el dato reportado es consumo, no dinero."},{"id":"C","texto":"Entre marzo y julio también cambió la estación, y con ella el uso de calefacción e iluminación","diagnostico":"Clave."},{"id":"D","texto":"El aislante podría estar mal instalado","diagnostico":"Cuestiona la intervención, no el razonamiento. Si estuviera mal instalado, el diseño seguiría sin poder demostrarlo."}]'::jsonb, 'C', 'ok', '{"unidad_rol":"contexto","estado_revision":"revisado_docente","razonamiento_esperado":"La comparación atribuye a la intervención un cambio que ocurrió junto con otro cambio de igual o mayor magnitud. Sin una casa comparable sin aislante, o sin el mismo mes de años anteriores, el efecto del aislante no puede separarse del efecto de la estación.","por_que_no_mide_contenido":"No exige saber cómo funciona un aislante ni calcular consumo. Exige notar que dos cosas cambiaron a la vez."}'::jsonb)
on conflict (framework_id, framework_version, item_id, item_version) do update set unit_code = excluded.unit_code, criterion_code = excluded.criterion_code, axis_code = excluded.axis_code, stimulus_format = excluded.stimulus_format, stimulus = excluded.stimulus, prompt = excluded.prompt, alternatives = excluded.alternatives, answer_key = excluded.answer_key, answer_key_status = excluded.answer_key_status, metadata = excluded.metadata;

