values ('paes-ciencias', 'admision-2027.v1', 'D-03', '1.0', 'QUI-03.10', 'HC-04.C1', 'Química', 'muestreo_sesgado', '{"tipo":"texto","texto":"Para evaluar la calidad del agua de un río que atraviesa una zona industrial, un equipo toma seis muestras. Las seis se recogen en el mismo punto, ubicado antes de que el río pase frente a las industrias, y todas el mismo día a las 8 de la mañana. Los análisis no detectan contaminantes, y el equipo concluye que el río no está contaminado.","texto_alternativo":"Seis muestras de un río se toman en un único punto aguas arriba de las industrias y a una sola hora; no se detectan contaminantes y se generaliza al río completo."}'::jsonb, '¿Qué limita principalmente esta conclusión?', '[{"id":"A","texto":"Todas las muestras provienen de un punto y un momento que no representan al río completo","diagnostico":"Clave."},{"id":"B","texto":"Seis muestras son muy pocas para un análisis químico","diagnostico":"Confunde cantidad con representatividad: 600 muestras del mismo punto tendrían el mismo problema."},{"id":"C","texto":"No se indica qué contaminantes específicos se buscaron","diagnostico":"Objeción razonable sobre el método analítico, pero secundaria frente a dónde se tomó la muestra."},{"id":"D","texto":"El análisis debería repetirse en un laboratorio distinto","diagnostico":"Cuestiona la confiabilidad del laboratorio, no el muestreo."}]'::jsonb, 'A', 'ok', '{"unidad_rol":"contexto","estado_revision":"revisado_docente","razonamiento_esperado":"La conclusión abarca \"el río\" y la evidencia cubre un punto aguas arriba de la fuente sospechada, en un único momento. El problema no es cuántas muestras se tomaron, sino de dónde y cuándo: más muestras del mismo lugar no corrigen el sesgo.","por_que_no_mide_contenido":"No exige conocer contaminantes ni técnicas analíticas. La falla está en la relación entre lo muestreado y lo concluido."}'::jsonb)
on conflict (framework_id, framework_version, item_id, item_version) do update set unit_code = excluded.unit_code, criterion_code = excluded.criterion_code, axis_code = excluded.axis_code, stimulus_format = excluded.stimulus_format, stimulus = excluded.stimulus, prompt = excluded.prompt, alternatives = excluded.alternatives, answer_key = excluded.answer_key, answer_key_status = excluded.answer_key_status, metadata = excluded.metadata;

